void Add(string name,Action<GalaxyState>?setup,Command[]commands,bool hostile=true,bool throwHostility=false){var w=World();setup?.Invoke(w);var stub=new StubHostility(hostile,throwHostility);var sim=new CombatSimulation(stub);var args0=Freeze(new{World=Snapshot(w),Commands=commands,Hostile=hostile,ThrowHostility=throwHostility});var before=Freeze(Snapshot(w));var results=new List<object>();foreach(var c in commands){object?raw=null;Exception?caught=null;try{raw=c.Kind switch{"Order"=>sim.IssueOrder(w,c.CivilizationId,c.FleetId,new MilitaryOrder(c.OrderType,c.TargetFleetId,c.DefendSystemId)),"Advance"=>sim.Advance(w,c.Days),"Summary"=>sim.GetOwnMilitaryForceSummary(w,c.CivilizationId),_=>throw new InvalidOperationException("Unknown oracle command")};}catch(Exception e){caught=e;}var result=Freeze(raw);var error=caught is null?(JsonElement?)null:Freeze(new{Type=caught.GetType().Name,caught.Message});results.Add(new{Command=Freeze(c),Result=result,Error=error,After=Freeze(Snapshot(w))});}cases.Add(new{Name=name,Arguments=args0,Before=before,Result=Freeze(results),After=Freeze(Snapshot(w)),HostilityCalls=Freeze(stub.Calls)});}
