Add("order-attack-unarmed",w=>w.Fleets[0].Combat=Combat("civilian_light_v1"),new[]{Order(MilitaryOrderType.Attack,target:2)});Add("order-attack-no-target",null,new[]{Order(MilitaryOrderType.Attack)});Add("order-attack-missing-target",null,new[]{Order(MilitaryOrderType.Attack,target:99)});Add("order-attack-inactive-target",w=>w.Fleets[1].IsActive=false,new[]{Order(MilitaryOrderType.Attack,target:2)});Add("order-attack-friendly",w=>w.Fleets[1]=Fleet(2,1,"Beta"),new[]{Order(MilitaryOrderType.Attack,target:2)});Add("order-attack-other-system",w=>w.Fleets[1].CurrentSystemId=20,new[]{Order(MilitaryOrderType.Attack,target:2)});Add("order-attack-target-disengaged",w=>{w.Fleets[1].Combat!.IsDisengaged=true;w.Fleets[1].Combat!.DisengagedSystemId=10;},new[]{Order(MilitaryOrderType.Attack,target:2)});Add("order-attack-peaceful",null,new[]{Order(MilitaryOrderType.Attack,target:2)},false);Add("order-unknown",null,new[]{Order((MilitaryOrderType)99)});
Add("order-sequence-reset",w=>{var s=w.Fleets[0].Combat!;s.IsDisengaged=true;s.DisengagedSystemId=10;s.RetreatProgressDays=2;s.RetreatStarted=true;},new[]{Order(MilitaryOrderType.Hold),Order(MilitaryOrderType.Defend),Order(MilitaryOrderType.Retreat)});
