Add("advance-unthreatened-retreat",w=>w.Fleets[0].Combat!.Order=MilitaryOrderType.Retreat,new[]{Advance(.1)});Add("advance-retreat-threshold-below",w=>{AttackSetup(w);w.Fleets[1].Combat!.Order=MilitaryOrderType.Retreat;w.Fleets[1].Combat!.RetreatProgressDays=.7499998;},new[]{Advance(.75)});Add("advance-retreat-threshold-epsilon",w=>{AttackSetup(w);w.Fleets[1].Combat!.Order=MilitaryOrderType.Retreat;w.Fleets[1].Combat!.RetreatProgressDays=.7499999;},new[]{Advance(.75)});
Add("advance-destroy-civilian-population",w=>{AttackSetup(w);var s=w.Fleets[1].Combat!;s.Shields=0;s.Armor=0;s.Hull=1;},new[]{Advance(.75)});Add("advance-shield-armor-hull",w=>{AttackSetup(w);var s=w.Fleets[1].Combat!;s.Shields=5;s.Armor=5;s.Hull=30;},new[]{Advance(.75)});Add("advance-simultaneous-destruction",w=>{AttackSetup(w);w.Fleets[1].Combat!.Order=MilitaryOrderType.Attack;w.Fleets[1].Combat!.TargetFleetId=1;foreach(var f in w.Fleets){f.Combat!.Shields=0;f.Combat!.Armor=0;f.Combat!.Hull=1;}},new[]{Advance(.75)});
