sealed record Command(string Kind,int CivilizationId=0,int FleetId=0,MilitaryOrderType OrderType=MilitaryOrderType.Hold,int?TargetFleetId=null,int?DefendSystemId=null,double Days=0);
sealed class StubHostility(bool hostile,bool throwHostility):ICombatHostilityView{public List<object>Calls{get;}=new();public bool AreHostile(int a,int b){Calls.Add(new{FirstCivilizationId=a,SecondCivilizationId=b});if(throwHostility)throw new InvalidOperationException("Hostility oracle failure.");return hostile;}}
